// Similar to ChatMessageBlock.tsx in escher

import { View } from 'react-native'
import { defineStyles } from '@/utils/defineStyles'
import { Block, ChatBlockType } from '../utils/types'
import { colors, Theme, useTheme } from '@/theme'
import { LLMTag, ToolCallTagArg, ToolCallTagStatus } from '../utils/llm-tags'
import { UIBlock, UIBlockData } from './UIBlock'
import { unescapeXML } from '@/utils/unescape-xml'
import { isEnumValue } from '../utils/composition'
import { ToolCall } from './ToolCall'
import { StreamingText } from '../hooks/useStreaming'
import { useChatStore } from '../store/chatStore'
import Markdown from 'react-native-markdown-display'

export const AssistantMessage = ({
	block,
	messageId,
	isGenerating,
	isLastBlock,
	shouldAnimate = true,
	isOnlyBlock,
	isLauncher
}: {
	block: Block
	messageId: string
	isGenerating: boolean
	isLastBlock: boolean
	shouldAnimate?: boolean
	isOnlyBlock: boolean
	isLauncher: boolean
}) => {
	const { theme } = useTheme()
	const currentMessageId = useChatStore((state) => state.value.currentMessageId)
	const chatState = useChatStore((state) => state.value.chatState)
	switch (block.type) {
		case ChatBlockType.TAG: {
			switch (block.tag) {
				case LLMTag.FILE_BASED_BLOCK: {
					const isString = (value: unknown): value is string =>
						typeof value === 'string'
					const uiType = block.args?.uiType
					if (!uiType || !isString(uiType)) {
						return null
					}

					let blockData: UIBlockData = {
						uiType: uiType,
						subtext: isString(block.args?.subtext)
							? unescapeXML(block.args.subtext)
							: '',
						text: isString(block.args?.text)
							? unescapeXML(block.args.text)
							: '',
						code: isString(block.args?.code)
							? unescapeXML(block.args.code)
							: undefined,
						domains: isString(block.args?.domains)
							? unescapeXML(block.args.domains)
							: '',
						status:
							typeof block.args?.status === 'string' &&
							isEnumValue(block.args.status, ToolCallTagStatus)
								? block.args.status
								: undefined,
						secrets: isString(block.args?.secrets)
							? unescapeXML(block.args.secrets).split(',')
							: undefined,
						thinkingType: isString(block.args?.thinkingType)
							? unescapeXML(block.args.thinkingType)
							: undefined,
						browserLiveUrl: isString(block.args?.browserLiveUrl)
							? unescapeXML(block.args.browserLiveUrl)
							: undefined,
						browserSize: isString(block.args?.browserSize)
							? unescapeXML(block.args.browserSize)
							: undefined,
						browserReplayUrl: isString(block.args?.browserReplayUrl)
							? unescapeXML(block.args?.browserReplayUrl)
							: undefined,
						browserCurrentUrl: isString(block.args?.browserCurrentUrl)
							? unescapeXML(block.args?.browserCurrentUrl)
							: undefined,
						updates: (() => {
							if (!isString(block.args?.updates)) return undefined
							try {
								const unescaped = unescapeXML(block.args.updates)
								if (!unescaped || unescaped.trim() === '') return undefined
								return JSON.parse(unescaped)
							} catch {
								return undefined
							}
						})()
					}

					const isLoading = blockData.status === ToolCallTagStatus.RUNNING
					const isCurrentlyGenerating = isGenerating

					if (!isCurrentlyGenerating) {
						blockData = {
							...blockData,
							status:
								blockData.status === ToolCallTagStatus.RUNNING
									? ToolCallTagStatus.SUCCESS
									: blockData.status
						}
					}

					return (
						<UIBlock
							data={blockData}
							isLatest={isCurrentlyGenerating && isLastBlock}
							isLoading={isCurrentlyGenerating && isLoading}
							shouldAnimate={shouldAnimate}
							isOnlyBlock={isOnlyBlock}
							messageId={messageId}
							isLauncher={isLauncher}
						/>
					)
				}
				case LLMTag.TOOL_CALL: {
					const textArg = block.args?.[ToolCallTagArg.TEXT]
					const hidden = block.args?.[ToolCallTagArg.HIDDEN] === 'true'
					const statusArg = block.args?.[ToolCallTagArg.STATUS]
					const text = typeof textArg === 'string' ? textArg : ''
					const status =
						typeof statusArg === 'string' &&
						isEnumValue(statusArg, ToolCallTagStatus)
							? statusArg
							: null
					return <ToolCall text={text} hidden={hidden} status={status} />
				}
				case LLMTag.FILE:
				case LLMTag.THINKING:
				case LLMTag.VIEW_TRANSITION:
				case LLMTag.DESIGN_SYSTEM_SELECTION:
					return null
			}
			return null
		}
		case ChatBlockType.CODE:
		case ChatBlockType.TEXT: {
			// markdown has built in margin top and bottom for paragraph
			const markDownStyle = {
				body: styles.text(theme),
				paragraph: {
					marginTop: 0,
					marginBottom: 0
				},
				code_inline: {
					backgroundColor: colors[theme].gray[50]
				}
			}

			return (
				<View style={styles.textContainer}>
					{messageId === currentMessageId && chatState === 'GENERATING' ? (
						<StreamingText
							text={block.code}
							customStyles={markDownStyle}
							lastStreamingText={!isGenerating}
						/>
					) : (
						<Markdown style={markDownStyle}>{block.code}</Markdown>
					)}
				</View>
			)
		}
		case ChatBlockType.SIGNUP:
		case ChatBlockType.ANIMATED_TEXT:
		case ChatBlockType.PROJECT_GROUP_TEMPLATE_EMAIL:
		case ChatBlockType.SELECTED_MODULE:
		case ChatBlockType.SELECTED_INTEGRATION:
		case ChatBlockType.SELECTED_DESIGN_SYSTEM:
		case ChatBlockType.TOMBSTONE:
		case ChatBlockType.EMAIL: {
			return null
		}
	}
	return null
}

const styles = defineStyles({
	textContainer: {
		paddingLeft: 28
	},
	text: (theme: Theme) => ({
		fontSize: 16,
		fontWeight: '500',
		color: colors[theme].gray[900],
		lineHeight: 24,
		gap: 8 // gap in between bodies of text
	})
})
